execution.parser_program:
$Cases = [Console]::In.ReadToEnd() | ConvertFrom-Json
$Results = foreach ($Case in $Cases) {
    $Tokens = $null; $ParseErrors = $null
    $null = [Management.Automation.Language.Parser]::ParseInput($Case.script, [ref]$Tokens, [ref]$ParseErrors)
    [ordered]@{
        case = $Case.name
        parser = $PSVersionTable.PSVersion.ToString()
        parser_platform = $PSVersionTable.Platform
        error_count = @($ParseErrors).Count
        errors = @($ParseErrors | ForEach-Object {
            [ordered]@{error_id=$_.ErrorId; line=$_.Extent.StartLineNumber; text=$_.Extent.Text; message=$_.Message}
        })
    }
}
$Results | ConvertTo-Json -Depth 6
